shader_type canvas_item;
render_mode unshaded;
#include "res://shaders/window_field.gdshaderinc"
uniform vec2 cast_dir=vec2(0.7,0.7);
uniform float cot_e=1.0;
uniform float strength=0.35;
// Set only for the departing actor's caster passes. Other room casters stay 1.
uniform float source_opacity=1.0;
uniform bool floor_clip=true;
uniform bool use_window=true;
uniform bool lamp_shadow=false;
uniform float penumbra_scale=1.0;
uniform float ground_y=950.0;
uniform float height_factor=0.6;
uniform vec2 source_origin=vec2(0.0);
uniform vec2 source_axis_x=vec2(1.0,0.0);
uniform vec2 source_axis_y=vec2(0.0,1.0);
// Home derivative: VERTEX is actual sprite-local geometry, independent of atlas UV.
uniform bool mesh_projection=false;
uniform bool soft_mesh_projection=false;
uniform vec2 projection_direction=vec2(0.0);
uniform float lift_height=0.0;
uniform vec4 texture_bounds=vec4(0.0,0.0,1.0,1.0);
varying vec2 world_pos;
varying vec2 source_world;
varying float source_height;
void vertex(){
    source_world=source_origin+source_axis_x*VERTEX.x+source_axis_y*VERTEX.y;
    source_height=max(ground_y-source_world.y,0.0);
    if(mesh_projection){
        float support_y=(round(COLOR.r*255.0)*256.0+round(COLOR.g*255.0))/16.0-2048.0;
        vec2 support=source_origin+source_axis_x*VERTEX.x+source_axis_y*support_y;
        support.y+=lift_height;
        if(soft_mesh_projection){support=vec2(source_world.x,support_y); }
        source_height=max(support.y-source_world.y,0.0);
        VERTEX=vec2(source_world.x,support.y)+projection_direction*source_height;
    }
    world_pos=(MODEL_MATRIX*vec4(VERTEX,0.0,1.0)).xy;
}
float inside_source(vec2 uv){
    return step(texture_bounds.x,uv.x)*step(texture_bounds.y,uv.y)*step(uv.x,texture_bounds.z)*step(uv.y,texture_bounds.w);
}
vec2 clamped_source_uv(vec2 uv,vec2 texel){
    // Keep bilinear footprints within this atlas entry, including the half texel.
    return clamp(uv,texture_bounds.xy+texel*0.5,texture_bounds.zw-texel*0.5);
}
void fragment(){
    float h=source_height*height_factor;
    // Penumbra grows away from grounded contact, to avoid cut-paper blocks.
    vec2 d=TEXTURE_PIXEL_SIZE*(2.0+clamp(h*0.045,0.0,9.0))*penumbra_scale;
    float a=texture(TEXTURE,clamped_source_uv(UV,TEXTURE_PIXEL_SIZE)).a*inside_source(UV)*0.24;
    a+=texture(TEXTURE,clamped_source_uv(UV+vec2(d.x,0.0),TEXTURE_PIXEL_SIZE)).a*inside_source(UV+vec2(d.x,0.0))*0.12;
    a+=texture(TEXTURE,clamped_source_uv(UV-vec2(d.x,0.0),TEXTURE_PIXEL_SIZE)).a*inside_source(UV-vec2(d.x,0.0))*0.12;
    a+=texture(TEXTURE,clamped_source_uv(UV+vec2(0.0,d.y),TEXTURE_PIXEL_SIZE)).a*inside_source(UV+vec2(0.0,d.y))*0.12;
    a+=texture(TEXTURE,clamped_source_uv(UV-vec2(0.0,d.y),TEXTURE_PIXEL_SIZE)).a*inside_source(UV-vec2(0.0,d.y))*0.12;
    a+=texture(TEXTURE,clamped_source_uv(UV+d*0.707,TEXTURE_PIXEL_SIZE)).a*inside_source(UV+d*0.707)*0.07;
    a+=texture(TEXTURE,clamped_source_uv(UV-d*0.707,TEXTURE_PIXEL_SIZE)).a*inside_source(UV-d*0.707)*0.07;
    a+=texture(TEXTURE,clamped_source_uv(UV+vec2(d.x,-d.y)*0.707,TEXTURE_PIXEL_SIZE)).a*inside_source(UV+vec2(d.x,-d.y)*0.707)*0.07;
    a+=texture(TEXTURE,clamped_source_uv(UV+vec2(-d.x,d.y)*0.707,TEXTURE_PIXEL_SIZE)).a*inside_source(UV+vec2(-d.x,d.y)*0.707)*0.07;
    float g=min(window_field(world_pos,cast_dir,cot_e),window_field(source_world,cast_dir,cot_e));
    if(!use_window){g=1.0;}
    if(lamp_shadow){
        float r=length(world_pos-vec2(465.0,468.0))/672.0;
        float falloff=r<0.35?mix(1.0,0.45,r/0.35):mix(0.45,0.0,clamp((r-0.35)/0.65,0.0,1.0));
        g*=falloff;
    }
    if(floor_clip){g*=smoothstep(738.0,748.0,world_pos.y);}
    COLOR=vec4(0.10,0.075,0.055,a*strength*g*source_opacity);
}

shader_type canvas_item;
// Independent incense: V3 illumination with cylindrical, fibrous shaft albedo.
uniform float rod_length=224.0;
uniform float ember_strength=1.0;
#include "res://shaders/window_field.gdshaderinc"
#include "res://shaders/outdoor_window.gdshaderinc"
uniform vec3 ambient_color = vec3(0.55);
uniform vec3 sun_color = vec3(1.0,0.85,0.62);
uniform vec3 sun_vector = vec3(-0.6,-0.4,0.7);
uniform vec2 cast_dir = vec2(0.6,0.6);
uniform float sun_energy = 1.0;
uniform float cot_e = 1.0;
uniform vec2 moon_cast_dir = vec2(-0.32,0.95);
uniform float moon_energy = 0.0;
uniform float surface_type = 1.0;
uniform float lamp_glow = 0.0;
uniform vec4 visible_uv = vec4(0.0,0.0,1.0,1.0);
uniform bool show_mask = false;
uniform float daylight=1.0;
uniform float game_hour=12.0;
uniform bool outdoor_enabled=true;
uniform float morning_weight=0.0;
uniform float noon_weight=0.0;
uniform float sunset_weight=0.0;
uniform float afterglow_energy=0.0;
varying vec2 world_pos;
varying vec4 source_albedo;
varying vec3 surf_normal;
varying float exterior_mask;
void vertex(){world_pos = (MODEL_MATRIX*vec4(VERTEX,0.0,1.0)).xy;}
void fragment(){
    source_albedo=texture(TEXTURE,UV);
    // Fixed physical grain spacing as the top burns down, never stretched paint.
    float from_base=(1.0-UV.y)*rod_length;
    float grain=sin(UV.x*53.0+sin(from_base*0.24)*0.7)*0.045;
    grain+=sin(from_base*7.3+UV.x*91.0)*sin(from_base*1.83)*0.027;
    float cylinder=sqrt(max(1.0-pow((UV.x-0.5)*2.4,2.0),0.0));
    source_albedo.rgb=vec3(0.56,0.35,0.17)*(0.63+0.37*cylinder)+vec3(grain);
    float from_tip=UV.y*rod_length;
    float ash=1.0-smoothstep(1.0,3.8,from_tip);
    source_albedo.rgb=mix(source_albedo.rgb,vec3(0.34,0.32,0.28),ash*0.76);
    vec2 q=(UV-visible_uv.xy)/max(visible_uv.zw,vec2(0.001));
    vec2 xy=(q-vec2(0.5,0.58))*2.0;
    vec3 normal=normalize(vec3(xy.x*0.68,xy.y*0.3,0.9));
    if(surface_type<0.5){
        normal=world_pos.y>742.0?vec3(0.0,0.0,1.0):normalize(vec3(0.0,-0.95,0.31));
    }
    if(surface_type>1.5){normal=normalize(vec3(xy.x*0.18,-0.5,0.8));}
    normal=normalize(vec3((UV.x-0.5)*1.6,0.02,max(cylinder,0.20)));
    surf_normal=normal;
    // Manual sun is a finite, height-aware 2.5D pass. Native PointLight2D
    // remains active below for the warm lamp. UI has no lighting material.
    float gate=window_field(world_pos,cast_dir,cot_e);
    float lambert=max(dot(normal,sun_vector),0.0);
    vec3 illumination=ambient_color+sun_color*sun_energy*gate*(0.20+0.80*lambert);
    float moon_gate=window_field(world_pos,moon_cast_dir,1.6);
    illumination+=vec3(0.28,0.43,0.80)*moon_energy*moon_gate*(0.24+0.35*max(normal.z,0.0));
    // Evening afterglow stays bounded to the window-lit receiver region.
    illumination+=vec3(1.0,0.29,0.11)*afterglow_energy*gate*(0.24+0.35*max(normal.z,0.0));
    vec3 lit=source_albedo.rgb*illumination;
    // A gentle highlight shoulder keeps strong noon light without clipping IP paint.
    float peak=max(lit.r,max(lit.g,lit.b));
    if(peak>0.90){lit*=((0.90+0.09*(1.0-exp(-(peak-0.90)/0.09)))/peak);}
    if(surface_type>2.5){
        float globe=1.0-smoothstep(0.70,1.0,length((UV-vec2(0.430,0.689))/vec2(0.229,0.208)));
        lit+=vec3(1.0,0.78,0.40)*lamp_glow*globe*0.66;
    }
    exterior_mask=surface_type<0.5?outdoor_aperture(world_pos):0.0;
    if(outdoor_enabled && exterior_mask>0.0){lit=mix(lit,outdoor_scene(world_pos,source_albedo.rgb,daylight,game_hour,morning_weight,noon_weight,sunset_weight,afterglow_energy),exterior_mask);}
    float ember=1.0-smoothstep(0.35,2.0,from_tip);
    lit+=vec3(1.0,0.17,0.015)*ember*ember_strength;
    COLOR=vec4(lit,source_albedo.a);
    if(show_mask){COLOR=vec4(mix(vec3(0.06,0.10,0.13),vec3(1.0,0.73,0.24),gate*sun_energy),source_albedo.a);}
    NORMAL=normalize(vec3(normal.xy,normal.z));
}
void light(){
    float diffuse=0.55+0.45*max(dot(surf_normal,LIGHT_DIRECTION),0.0);
    LIGHT=vec4(source_albedo.rgb*LIGHT_COLOR.rgb*LIGHT_ENERGY*diffuse*(1.0-exterior_mask),LIGHT_COLOR.a*source_albedo.a);
}

